<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$s=db()->prepare('SELECT r.*,u.full_name requester_name,u.shop_name requester_shop,a.full_name accepted_by_name FROM product_requests r JOIN users u ON u.id=r.requester_id LEFT JOIN users a ON a.id=r.accepted_by WHERE r.requester_id=? OR (r.status="open" AND r.requester_id!=?) ORDER BY r.created_at DESC');$s->execute([$u['id'],$u['id']]);out(['success'=>true,'requests'=>$s->fetchAll()]);
